mapper.select:
select "销售金额" name, ifnull(sum(p.detailsAmount),0) value -- 销售金额 from ( SELECT so.user_id userId, -- 业务员 DATE_FORMAT(so.delivery_time,"%Y-%m") deliveryTime, -- 交货日期 sod.details_amount detailsAmount, -- 销售金额 ifnull(omp.materiel_num,0)* ifnull(sod.details_price,0) offAmount-- 已送货金额 FROM brt_sales_order so INNER JOIN brt_sales_order_details sod on sod.order_id = so.order_id LEFT JOIN brt_order_materiel_plan omp on omp.order_details_id = sod.details_id GROUP BY sod.details_id )p
and p.userId = #{map.userId}
and p.deliveryTime = #{map.queryDate}
union all
select "已送货金额" name, ifnull(sum(p.offAmount),0) value -- 已送货金额 from ( SELECT so.user_id userId, -- 业务员 DATE_FORMAT(so.delivery_time,"%Y-%m") deliveryTime, -- 交货日期 sod.details_amount detailsAmount, -- 销售金额 ifnull(omp.materiel_num,0)* ifnull(sod.details_price,0) offAmount-- 已送货金额 FROM brt_sales_order so INNER JOIN brt_sales_order_details sod on sod.order_id = so.order_id LEFT JOIN brt_order_materiel_plan omp on omp.order_details_id = sod.details_id GROUP BY sod.details_id )p
and p.userId = #{map.userId}
and p.deliveryTime = #{map.queryDate}
union all
select "未送货金额" name, ifnull(sum(p.detailsAmount)-sum(p.offAmount),0) value -- 未送货金额 from ( SELECT so.user_id userId, -- 业务员 DATE_FORMAT(so.delivery_time,"%Y-%m") deliveryTime, -- 交货日期 sod.details_amount detailsAmount, -- 销售金额 ifnull(omp.materiel_num,0)* ifnull(sod.details_price,0) offAmount-- 已送货金额 FROM brt_sales_order so INNER JOIN brt_sales_order_details sod on sod.order_id = so.order_id LEFT JOIN brt_order_materiel_plan omp on omp.order_details_id = sod.details_id GROUP BY sod.details_id )p
and p.userId = #{map.userId}
and p.deliveryTime = #{map.queryDate}

select p.deptName, sum(ifnull(p.ans,0)) onTime, -- 按时完成数 (sum(ifnull(p.ans,1)) - sum(ifnull(p.ans,0))) unOnTime -- 未按时完成数 from (
SELECT DATE_FORMAT(o.finish_date,"%Y-%m-%d") finishTime, d.dept_name deptName, -- 部门名称 case when n.complate_date is null or DATE_FORMAT(n.update_time,"%Y-%m-%d") <= DATE_FORMAT(n.complate_date,"%Y-%m-%d") then 1 end ans FROM brt_sales_order o inner JOIN brt_order_template t on o.order_id = t.order_id inner join brt_order_node n on n.order_template_id = t.order_template_id inner join sys_dept d on d.dept_id = n.dept_id where n.node_status = '2'
)p
and p.finishTime > #{map.queryDateStart}
and p.finishTime < #{map.queryDateEnd}
-- where p.finishTime GROUP BY p.deptName
